INSERT INTO `ck_characters` (`char_key`, `name`, `role`, `trait`, `sort_no`) VALUES ('1','陳一承','宿舍自治會生活股股長','熟悉公共廚房規則與冰箱巡查，相信自己的固定流程',1);
INSERT INTO `ck_characters` (`char_key`, `name`, `role`, `trait`, `sort_no`) VALUES ('2','葉二寧','食品科學系學生','常協助整理與標示冷藏食物，習慣先動手把東西歸位',2);
INSERT INTO `ck_characters` (`char_key`, `name`, `role`, `trait`, `sort_no`) VALUES ('3','高三川','宿舍社群管理員','消息靈通，擅長帶話題，也擅長把話題帶到別的方向',3);
INSERT INTO `ck_characters` (`char_key`, `name`, `role`, `trait`, `sort_no`) VALUES ('4','羅四影','攝影社學生','常拍攝宿舍活動與剪輯短片，手上有那段十二秒影片',4);
INSERT INTO `ck_characters` (`char_key`, `name`, `role`, `trait`, `sort_no`) VALUES ('5','許五澄','資工系學生','曾協助維護宿舍智慧冰箱標籤系統，最熟悉後台',5);
INSERT INTO `ck_characters` (`char_key`, `name`, `role`, `trait`, `sort_no`) VALUES ('6','蔡六禾','樓層總務','負責代收包裹與公共區域物資，常提著保冷袋進出廚房',6);
INSERT INTO `ck_levels` (`level_no`, `name`, `skills`, `task`, `reasonable_count`, `video_src`, `video_script`, `conclusion`, `ranking_criterion`, `ai_feedback_opening`) VALUES (1,'B-9 空了','找證據：真實性、可靠性／有效性、相關性、代表性、事實與意見、目擊證詞','六名角色只陳述食物失蹤前後自己所看見、聽見或親自經歷的片段。先圈出可觀察事實，再區分記憶、推測與結論，判斷每項證詞能支持到哪個範圍。',2,'media/intro-L1.mp4','霧城大學七舍使用 COLD-6 智慧冰箱管理公共廚房的冷藏物品。\n週五晚上，住戶蘇予安將一盒價值新臺幣 2,680 元的月蝕巧克力莓果千層蛋糕放進 B-9 層，盒上貼有姓名與「私人物品」標籤。\n晚上十點後，陳一承、葉二寧、高三川、羅四影、許五澄與蔡六禾六名學生先後出現在交誼廳與公共廚房附近。\n\n23:00 點左右，蘇予安回來取食物時，櫃位 B-9 已經空了，只剩一小段被撕下的透明膠帶。\n走廊監視器沒有正對冰箱內部；COLD-6 的系統紀錄則顯示：「22:47:09｜B-9 標籤狀態異常。」\n羅四影交出一段十二秒影片：畫面中蔡六禾打開冰箱、手伸向下層；鏡頭晃開後，再切回來時 B-9 已經空了。\n陳一承匯出值勤紀錄，最後一行寫著：「22:47:18｜人工確認｜標籤狀態已接受。」','B-9 確實從有東西變成空的，這一點可以由兩人的目擊與系統紀錄支持。但「誰拿走」還沒有任何一項證據能直接指認——提著袋子不等於袋子裡是失物，時間接近也不等於同一個動作。','選出把觀察直接當成指認的說法：用間接線索指認人、用缺失畫面補完動作、用其他層架正常排除單點異常。理由要指出該說法從哪一項觀察跳到哪一個結論；只憑角色身分或說話語氣判斷不得分。','哪些是角色親眼看見、親耳聽見或親自經歷的？位置、視角、記憶與利害關係如何限制證詞？「拿著袋子」是否等於「袋子裡就是失物」？時間接近是否足以證明同一行為？');
INSERT INTO `ck_levels` (`level_no`, `name`, `skills`, `task`, `reasonable_count`, `video_src`, `video_script`, `conclusion`, `ranking_criterion`, `ai_feedback_opening`) VALUES (2,'好學生不會偷東西','辨認假設：假設、隱性假設、偽前提、意識形態假設','群組轉傳、收回訊息、角色專業與「好學生不會偷」「新系統應該可靠」的想像混在一起。判斷哪些說法把職務、專業、緊張反應或系統可靠度當成自明前提。',2,'media/intro-L2.mp4','隔天早上，十二秒影片在宿舍群組被大量轉傳。\n有人把畫面停在蔡六禾伸手進冰箱的瞬間，字幕寫著：「總務拿走 2,680 元蛋糕？」\n\n蔡六禾先輸入：「我只是把那盒移到……」幾秒後又把訊息收回。\n她在宿舍會議裡一直捏著保冷袋的背帶，說話也比平常快。\n\n另一個匿名帳號留言：「新冰箱不會說謊；懂系統的人才有辦法讓紀錄看起來正常。」','「受過訓練所以不會出錯」「懂系統所以就是她」「緊張所以心虛」「新系統不會單點失敗」——這四句都不是自明的。在有裝置、位置與操作內容的紀錄之前，它們只是前提，不是證據。','選出依賴未驗證前提最重的說法：把專業能力當成實際操作、把情緒反應當成罪責指標、把整體可靠度當成單點必然正常。理由要明確寫出「這個結論依賴哪個沒說出口的前提」。','每句話依賴哪些未說出的前提？是否把職務、專業、緊張反應或「新系統不會局部失敗」當成自明事實？');
INSERT INTO `ck_levels` (`level_no`, `name`, `skills`, `task`, `reasonable_count`, `video_src`, `video_script`, `conclusion`, `ranking_criterion`, `ai_feedback_opening`) VALUES (3,'22:14 的共用帳號','演繹推論：三段論法、無效演繹、肯定前件、否定後件、選言三段論','共用帳號、位置紀錄、維護模式與缺失影片同時出現。把每句話拆成前提與結論，確認推論形式是否有效，並檢查結論是否超過紀錄能證明的範圍。',2,'media/intro-L3.mp4','校方資訊組查看 COLD-6 的維護資料，並匯出共用平板登入紀錄。\n晚上 22:14:03，「ice-admin」在公共廚房的維護平板登入；22:14:26，B-9 的標籤模板被更新。\n\n許五澄說自己的門禁紀錄顯示她當時在自習室，沒有拿著廚房平板。\n但她也承認，為了方便值勤人員處理故障，維護平板保留了自動登入設定。\nCOLD-6 操作手冊顯示，管理員帳號可輸入四位數值勤碼略過標籤警示，但紀錄只會標示「人工確認」，不會留下個人姓名。\n\n一樓代收區紀錄顯示，蔡六禾在 22:14 左右正在簽收冷藏包裹。\n羅四影的原始檔從 22:46:52 直接跳到 22:47:23，正好少了三十一秒。\n同一時間系統另有兩行訊息：「22:47:09｜B-9 私人物品標籤不一致」；「22:47:18｜人工確認｜警示已略過。」','前提看起來都成立，推論形式卻可以是壞的。共用帳號只證明模式被用過，證明不了人；影片有缺口推不出缺的是什麼；不在修改現場，也推不出整件事無關。','選出推論形式錯誤最嚴重的說法：肯定後件、假兩難、把帳號或裝置等同實際操作者、把「不在場」當成「無關」。理由要寫出「前提是什麼、結論是什麼、哪一步跳掉了」。','即使前提看似真實，結論是否必然成立？角色是否犯了肯定後件、假兩難，或把帳號、裝置與實際操作者混為一談？');
INSERT INTO `ck_levels` (`level_no`, `name`, `skills`, `task`, `reasonable_count`, `video_src`, `video_script`, `conclusion`, `ranking_criterion`, `ai_feedback_opening`) VALUES (4,'消失的三十一秒','解釋因果關係：錯誤因果、假相關、居前為因、假因果、必要條件與充分條件','備份影片、私人物品警示、臨時移動與收拾壓力被串在一起。判斷角色如何說明究竟是哪一個人、哪個環節「造成」蛋糕失竊。',1,'media/intro-L4.mp4','校方從電梯口備份相機找回消失的三十一秒。\n畫面顯示蔡六禾從冰箱拿出的只是兩瓶貼有「公共飲料」標籤的氣泡水。\n接著葉二寧把蘇予安的月蝕巧克力莓果千層蛋糕從 B-9 移到公共料理桌，說要先騰出冰箱空間。\n\n盒上的姓名貼紙仍在，但桌上同時出現一張橘色「公共聚餐」貼紙，位置緊靠月蝕巧克力莓果千層蛋糕。\nCOLD-6 隨即跳出紅色警示：「B-9 私人物品標籤不一致；請確認物品歸屬。」\n\n陳一承看了一眼說：「下午也誤報兩次，應該又是標籤感應問題。」\n高三川在門口催促：「等一下要夜間點名，先把桌子收乾淨比較要緊，明天再慢慢檢查。」\n陳一承輸入值勤碼，畫面改成「警示已略過」。幾分鐘後，料理桌上的月蝕巧克力莓果千層蛋糕不見了。','沒有單一原因。移動盒子、公共貼紙造成的標示混淆、警示被人工略過、收拾壓力，各自都不足以造成失竊，但合起來讓一盒有名字的蛋糕變成「桌上可以拿的東西」。時間先後不等於因果。','選出因果推論錯誤最嚴重的說法：居前為因、把共現當因果、把壓力當成免責、把單一動作說成全部責任、把人工確認當成充分證據。理由要指出該說法混淆了必要、促成或背景中的哪一種。','哪些只是時間先後或接近結果？哪些是直接原因、促成條件、必要條件或充分條件？多個因素能否共同構成一條因果鏈？');
INSERT INTO `ck_levels` (`level_no`, `name`, `skills`, `task`, `reasonable_count`, `video_src`, `video_script`, `conclusion`, `ranking_criterion`, `ai_feedback_opening`) VALUES (5,'蛋糕到底去了哪裡','歸納推論：歸納式結論、歸納式推論、邏輯順序、跳躍式推論／紙牌城堡、以偏概全','重量紀錄、備份影片、標籤狀態、過去誤報與群組片段形成多組模式。判斷角色根據有限樣本提出的物品流向與共謀解釋是否過度概括。',2,'media/intro-L5.mp4','調查小組把不同來源的資料分開核對。\nB-9 的重量感測顯示，月蝕巧克力莓果千層蛋糕先離開冰箱；公共料理桌的感測紀錄在相近時間增加約 1.7 公斤，幾分鐘後又恢復原值。\n蘇予安當晚拍的照片顯示，月蝕巧克力莓果千層蛋糕原本有完整姓名與「私人物品」貼紙。\n\n系統測試紀錄顯示，下午兩次標籤誤報都發生在空層架測試，與本次放有實體私人物品的情境不同。\n許五澄找到自己先前傳給值勤群的訊息：「測試後請登出共用平板，並清除『公共聚餐』標籤模板。」訊息顯示已讀，卻沒有人回報完成。\n\n晚間宿舍自習室的團體照片拍到六人桌上有相同品牌的蛋糕外盒，但照片角度不足以辨認盒上原本的姓名貼紙。\n校方也還原部分被刪除的群組訊息，其中有人在失竊前問：「今晚要不要把那盒一起吃了？」','多個彼此獨立的來源——備份影片、重量變化、警示與人工確認的時間——指向同一條路徑：蛋糕被移到公共桌、標示混淆、警示被略過，然後離開廚房。但「較可能」不是「已證明」，誰起意、誰知情，還沒有答案。','選出樣本問題與推論鏈問題最嚴重的說法：用空層架誤報概括本次私人物品警示、用「平常沒出事」概括這一次、用過去代收經驗概括本次行為、把連續猜測疊成主謀結論。理由要說明樣本從哪來、為什麼不足以支持那個結論。','哪些結論由多個相互獨立的模式支持？哪些只靠少量案例、非代表性樣本或過往經驗便概括本案？機率性結論是否被說成絕對證明？');
INSERT INTO `ck_levels` (`level_no`, `name`, `skills`, `task`, `reasonable_count`, `video_src`, `video_script`, `conclusion`, `ranking_criterion`, `ai_feedback_opening`) VALUES (6,'沒有人單獨偷走，誰該負責？','論證：論點一致性、邏輯一致性、獨立理由、聯合理由、以理服人、必要與充分條件','完整時間線、還原群組訊息、物品流向與後續剪輯被整合。判斷角色是否分清共同意圖、個別行為、促成作用與事後誤導。',1,'media/intro-L6.mp4','校方最後還原了完整群組備份、公共區域影片與物品流向。\n訊息顯示，六人私下組成名為「夜食會」的群組，過去曾多次把宿舍裡價格較高的私人物品說成「沒人會追究的小物共享」，並彼此約定被詢問時只描述自己看到的片段。\n這一次，六人都知道蛋糕屬於蘇予安，仍在群組中同意晚上一起分食。\n\n許五澄未登出共用平板並留下測試標籤模板；葉二寧把蛋糕移到公共料理桌；陳一承看見私人物品警示後仍人工略過。\n高三川催促大家迅速收桌，並在失竊後用二選一說法把群組注意力引向其他人；蔡六禾把裝有蛋糕的保冷袋帶到自習室。\n羅四影事後剪掉關鍵三十一秒，使最初流傳的影片看起來像蔡六禾單獨從冰箱拿走蛋糕。\n\n自習室影像與回收包裝證實六人共同分食蘇予安的月蝕巧克力莓果千層蛋糕。\n蘇予安在調查會議上問：「如果沒有任何一個人能單獨完成整件事，到底誰該為了偷吃蛋糕及事後掩護負責？」','沒有任何一個人能單獨完成整件事，但那不等於沒有人負責。共同意圖、各自的促成行為、以及事後的誤導與資訊傷害，是三件要分開評估的事。「不是唯一必要條件」只能削弱程度，不能歸零。','選出論證問題最嚴重的說法：用「不是唯一必要條件」免除責任、承認前置行為卻把責任推給最後搬袋者、用「發生在之後」排除事後誤導的傷害、把制度缺陷與事後好處當成抵銷理由。理由要指出哪些理由能獨立成立、哪些必須聯合，以及結論有沒有超出理由範圍。','主張是否前後一致？理由能否獨立成立或必須聯合使用？「不是唯一必要條件」是否等於「沒有責任」？又該如何分開評估失竊與事後誤導造成的傷害？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (1,'1','月蝕巧克力莓果千層蛋糕失蹤前，我在公共廚房門口看見智慧冰箱的紅色提示燈短暫亮起，後來才走近查看。當時走廊有人聊天，我沒有看清完整警示內容；我只能確定紅燈曾出現，門口監視器應該能確認。','reasonable','交代自己的位置、直接看到的紅燈與未看清文字的限制；最多支持「警示燈曾亮起」，不能直接推出警示內容或誰操作過系統。','紅燈能支持哪些最小事實？還需哪些畫面或系統紀錄才能確認警示內容與後續處理？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (1,'2','我在晚間九點多看到予安把寫有姓名的蛋糕禮盒放進 B-9 櫃位，後來回來時那一格已經空了。我沒有看見誰把盒子拿走，也不知道中間有沒有人移動它。','reasonable','只陳述自己看到予安放入蛋糕、之後層架變空，並明確承認沒有看到中間的取物過程；能支持物品狀態改變，不能識別拿取者。','她能確認哪些時間點與物品狀態？還需什麼證據才能判斷中間發生了什麼？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (1,'3','我從交誼廳往廚房看時，剛好看見蔡六禾提著保冷袋從冰箱旁走開；蘇予安說東西不見後，她又一直低頭不說話。她既靠近冰箱又拿著袋子，蛋糕應該就是她帶走的。','flaw','把「靠近冰箱、拿保冷袋、沉默」直接推成「帶走蛋糕」；這些都是間接線索，保冷袋內容與沉默原因仍有其他解釋。','保冷袋內容如何確認？沉默除了心虛還可能有哪些原因？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (1,'4','我的相機拍到蔡六禾打開冰箱，把手伸進下層；鏡頭轉開後，再切回來時 B-9 櫃位已經空了。雖然沒拍到她拿出月蝕巧克力莓果千層蛋糕，但兩段時間只差十幾秒，應該就是她拿走的。','flaw','影片只拍到開冰箱、鏡頭移開與 B-9 變空，缺少實際取出月蝕巧克力莓果千層蛋糕的關鍵畫面；不能只因時間相近就認定同一人拿走。','影片拍到什麼、沒有拍到什麼？缺失畫面可能有哪些替代情況？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (1,'5','那段時間我在自習室幫同學修電腦，沒有碰冰箱的維護平板。但事後系統顯示「物品標籤正常」；當晚其他層架的食物也都沒有失竊，所以這次不可能是系統或標籤造成的問題。','flaw','自己的不在場只能限制本人當時直接操作；「其他層架正常」與「標籤正常」不能排除 B-9 單一標籤、共用帳號或先前設定的異常。','她的不在場能排除哪些行為，不能排除哪些既有設定、共用登入或他人操作？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (1,'6','我打開冰箱只是拿飲料，沒有碰蘇予安的月蝕巧克力莓果千層蛋糕；當時也沒看見其他人拿走。因此如果東西真的不在，最可能是予安記錯位置，或她後來自己移走了。','flaw','「自己沒碰」與「沒看見別人拿」不能推出失物主人記錯；沒有看見不代表沒有發生，也不能把可能性縮成兩個選項。','她當時的視角有哪些限制？若要排除他人拿取，需要哪些獨立證據？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (2,'1','我負責宿舍公共廚房，也受過完整值勤訓練；每晚巡查都有固定流程。只要是我確認過的冰箱狀態，就表示物品標示一定沒有問題。','flaw','把「受過訓練」與「有固定流程」當成個別巡查一定正確的保證，隱含受訓者不會誤判、程序不會失效的假設。','訓練與流程能降低哪些風險，不能排除哪些誤判、例外或省略步驟？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (2,'2','蔡六禾平常做事很乾脆，但這次一直捏著保冷袋、說話很快，還把「我只是把那盒移到……」的訊息收回。這些反應太不自然，蛋糕失竊很可能就是她造成的。','flaw','把捏袋子、語速變快與收回訊息當成「很可能有罪」的指標，依賴緊張等於心虛、刪訊息等於掩罪的隱性假設。','若緊張來自被懷疑、工作壓力或訊息寫錯，各自會預測哪些不同證據？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (2,'3','許五澄是資工系，又最熟悉智慧冰箱後台；如果有人能改動 B-9 的標籤紀錄，最可能就是她。懂系統的人最有能力讓紀錄看起來正常。','flaw','由專業能力推到實際操作，再由能改系統推到能消除紀錄；忽略共用登入、其他操作者與設定本身留下痕跡的可能。','從「有能力」推到「實際做過」還缺少哪些裝置、位置與操作內容？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (2,'4','原始影片只拍到蔡六禾打開冰箱並拿出兩瓶公共飲料，畫面沒有顯示她碰到 B-9 的月蝕巧克力莓果千層蛋糕。她後來看起來緊張，也不能直接證明她拿走食物；還需要其他獨立紀錄。','reasonable','把影片的證明範圍限制在實際拍到的動作，並明確指出情緒不能替代取物證據；沒有把角色印象當成前提。','如何確認影片完整性與拍攝角度？還需要哪些紀錄補足未拍到的部分？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (2,'5','智慧冰箱是校方新換的系統，平常故障率很低，而且當晚其他層架都能正常辨識。既然系統大多時候可靠，這次 B-9 異常也應該不是系統造成，而是有人故意做手腳。','flaw','用整體故障率低、其他層架正常推成 B-9 也不可能局部異常；這依賴「可靠系統不會單點失敗」的隱性假設。','其他層架正常是否代表 B-9 必然正常？什麼資料可檢查單點異常？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (2,'6','宿舍群有人說「總務是最有機會碰公共冰箱的人」，但整層學生本來就能使用那台冰箱。我的職務只能說明我常出現在廚房，不能證明我拿過蛋糕；仍要看實際行為與紀錄。','reasonable','指出「總務常碰冰箱」只代表職務機會，不能推出實際偷竊；把身分與行為分開，要求以實際紀錄判斷。','職務身分能證明機會還是行為？哪一項資料最能連結本人與失物？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (3,'1','凡是只確認管理模式曾被使用，卻沒有留下實際操作者身分的紀錄，都不能直接判定是誰進行操作。現在共用平板只顯示管理模式曾被登入，因此不能僅憑這項紀錄推論是許五澄修改了 B-9 標籤。','reasonable','以「維護模式未記錄個人身分」限制結論，只能證明模式曾被使用，不能把共用帳號直接等同許五澄本人。','哪些資料只能證明模式或裝置被使用？還需哪些個人驗證才能識別操作者？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (3,'2','如果有人想掩蓋偷走蛋糕的過程，影片就會出現缺口；現在羅四影的檔案剛好少了三十一秒，所以缺掉的那段一定就是有人把蛋糕藏起來的畫面。','flaw','由「故意掩蓋可能造成影片缺口」反推「有缺口必是故意掩蓋」，屬肯定後件；即使缺口是人為，也尚未證明缺的是偷食畫面。','影片缺口還可能有哪些技術或剪輯原因？需要什麼證據才能連到故意掩蓋？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (3,'3','蛋糕不是被系統誤標成公共食物，就是被蔡六禾直接拿走。既然紀錄顯示蔡六禾在標籤修改時不在廚房，那就表示是許五澄用管理員帳號改了標籤設定。','flaw','先把可能性限縮成「系統誤標」或「蔡六禾直接拿走」，形成假兩難；排除六禾在某個時間點，也不能直接推出五澄操作。','原先兩個選項是否涵蓋他人操作、標示錯置或事後搬移？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (3,'4','我看到蔡六禾收回訊息後立刻接到電話，臉色也突然變僵；隨後她顯得比平時緊張。既然她是在收回訊息後才開始緊張，就表示那則訊息一定暴露了她參與偷吃蛋糕的事情。','flaw','把收回訊息、電話與緊張的時間順序直接推成訊息暴露犯罪；同時以「有罪者會緊張」反推「緊張者有罪」。','訊息內容與通話內容若不同，結論會如何改變？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (3,'5','要證明 B-9 的標籤修改導致蛋糕被當成公共食物，必須確認系統警示、標籤修改內容與蛋糕盒之間的關聯性。目前的紀錄只顯示設定被管理員帳號手動修改，尚不足以確認蛋糕的最後流向，因此也不能得知是誰拿走食物。','reasonable','列出從設定變動到實體物品被當成公共物品所需的必要前提，避免把「設定被改」直接當成「食物被拿」的證明。','哪一項紀錄能分別連結設定內容、實體盒子與後續取物行為？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (3,'6','如果是我偷走蛋糕，我在標籤被改的那一刻就應該在冰箱前操作；一樓代收紀錄可以證明我當時不在七樓，雖然我之後確實提過保冷袋，但整件事和我無關。','flaw','把「本人造成失竊」錯誤設定為必須在標籤修改時親自在冰箱前；即使當時不在場，後續搬運、訊息或其他共同作用仍可能相關。','一個人不在修改現場，仍可能透過哪些前後行為影響事件？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (4,'1','如果高三川沒有一直催大家快把公用的桌子清空，我就不會輸入確認碼略過 B-9 的標籤警示。下午也出現過兩次空層架誤報的訊息，所以我略過這次警示只是依照慣例處理，不是蛋糕被拿走的原因，真正問題是大家趕著夜間點名所以很匆忙。','flaw','把高三川的催促當成自己略過警示的主要原因，又用下午空層架誤報否定本次私人物品警示的因果作用；壓力能解釋決策，不等於消除操作的促成效果。','催促、輸入確認碼與警示各自是背景、促成條件還是必要條件？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (4,'2','盒子上的標籤被換過之後，共用帳號登入、冰箱警示和保冷袋移動也接連出現，最後蛋糕就不見了。這些異常總是一起發生，因此一定是標籤被換過造成系統誤把私人物品當成公共食物，才導致蘇予安的蛋糕不見。','flaw','名單、登入、警示與保冷袋時間接近只能顯示關聯；尚未證明「標籤修改」透過何種機制必然造成物品被帶走。','要證明標籤修改造成失竊，需要哪些物品流向與系統處理紀錄？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (4,'3','葉二寧先把月蝕巧克力莓果千層蛋糕從 B-9 移到公共料理桌，之後盒子才失蹤。既然她的移動發生在失竊之前，那個動作就是整件事的根本原因；如果她沒有搬動，蛋糕就不會被偷吃。','flaw','由「葉二寧先移動、之後失竊」直接認定移動是根本原因，屬居前為因；也沒有證明不移動就一定不會以其他方式失竊。','在沒有移動盒子但有人直接取走時，失竊是否仍可能發生？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (4,'4','備份影片清楚拍到葉二寧把「公共聚餐」的貼紙貼在月蝕巧克力莓果千層蛋糕旁。蛋糕盒原本有蘇予安的名字，是因為葉二寧貼錯標籤，所以才會有人誤以為蛋糕是派對用品，並把它帶到自習室；因此，蛋糕失竊應由她負全責。','flaw','二寧貼錯或保留公共貼紙可能是重要促成因素，但不足以單獨推出她應負全部責任；警示略過、搬運、共同意圖等因素仍可能獨立或聯合作用。','如果貼錯標籤但警示沒有略過，結果是否仍會相同？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (4,'5','系統只有在維護模式確認後才會把異常標籤視為有效，而紀錄顯示當晚確實有人按下人工確認。這足以證明後來拿走蛋糕的人是先透過後台改標籤；加上其他層架都正常，所以不可能只是誤會或臨時搬動造成。','flaw','把人工確認當成後續偷竊者必定先改標籤的充分證據；人工確認只證明系統狀態被接受，不能直接識別取物者或排除誤會。','人工確認可以證明什麼，不能證明誰實際拿走了物品？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (4,'6','蛋糕先被移到公共桌、私人物品警示又被略過，再加上大家急著收拾交誼廳，才讓蛋糕盒在混亂中被帶走。這些因素可能共同促成結果，不能只因其中一個動作最顯眼就把全部責任歸給一人。','reasonable','建立由移動、標示混淆、警示略過與收拾壓力共同組成的多因素因果鏈，並避免把單一角色當成全部原因。','在這條因果鏈中，哪些因素是可避免決策，哪些只是情境背景？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (5,'1','完整影片顯示蔡六禾從冰箱拿出的只是兩瓶公共氣泡水，沒有碰到 B-9；一樓紀錄也顯示她在標籤被修改時不在七樓。下午兩次標籤警示最後都證明是誤報，而且其他層架整晚正常，因此這次 B-9 的私人物品警示也不值得相信。既然過去幾次都沒有真的失竊，可以確定略過警示並不是蛋糕消失的關鍵原因。','flaw','由兩次空層架誤報與其他層架正常概括本次私人物品警示也不可信，樣本少且情境不同；又把「過去沒失竊」推成「本次警示與失竊無關」。','兩次空層架誤報與本次私人物品警示有哪些關鍵差異？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (5,'2','為了要重新整理層架，我確實有把月蝕巧克力莓果千層蛋糕從 B-9 移到料理桌。原本姓名貼紙仍在，但旁邊後來多了「公共聚餐」貼紙，系統立刻出現私人物品警示，接著又被人工略過。重量紀錄顯示盒子之後離開料理桌。因此較合理的推論是：蛋糕被移動、標示混淆與警示略過，共同造成了蛋糕被當成公共食物並被帶走；但這些證據仍不能證明誰最先起意，也不能只憑最後提袋的人判定整體共謀。','reasonable','把移動、公共貼紙、私人物品警示、人工略過與重量變化串成較可能路徑，同時保留「誰先起意」「是否整體共謀」仍需其他證據。','這條推論每一環節由哪項紀錄支持？要判斷共同意圖還缺什麼？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (5,'3','共用平板顯示有人修改過標籤，許五澄最懂後台，而且她也承認平板保留自動登入。帳號、設定、專業能力都指向她，所以應該是許五澄把蛋糕改成公共物品。她既然做了修改，就表示早就知道大家會把蛋糕分掉；既然知道結果，她就必定是整件事的主謀，其他人的行為只是配合她的安排。','flaw','從共用帳號、專業能力跳到五澄本人修改，再跳到她預知結果與主謀身分；每一步都建立在前一步尚未證明的假設上，形成紙牌城堡。','如何分別驗證實際操作者、修改內容、預知後果與主謀結論？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (5,'4','雖然下午發生過兩次標籤誤報，但當晚其他冰箱層架都正常，蘇予安的姓名貼紙也還在盒上。大家平常都很遵守規定，宿舍冰箱也沒有失竊紀錄。既然大部分時間系統與住戶都沒有問題，B-9 的紅色警示應該只是另一個誤報；蛋糕不見比較可能是蘇予安記錯，不能因為一次異常就懷疑同學。','flaw','以前幾週沒有失竊、其他層架正常與住戶平常守規矩，概括本次警示是誤報且予安記錯；樣本不代表這次特定高價物品與異常狀態。','「平常沒出事」能多大程度預測這一次？本案有哪些特有條件？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (5,'5','備份影片、B-9 的重量紀錄與人工確認時間彼此吻合：蛋糕先被移到公共桌，系統警示私人物品標籤不一致，之後有人略過警示，盒子才離開廚房。這些證據共同指向蛋糕不見是因為「系統警示標籤不一致卻被忽略」。但實際拿走的是誰以及其意圖為何仍需其他證據確認。','reasonable','多個獨立來源對同一時間順序做出一致預測，因此可用機率語言提出較合理的物品流向；並清楚保留操作者與共同意圖尚未確定。','哪一項新證據最能確認或推翻「標示混淆後被帶走」的解釋？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (5,'6','第一，影片證明我沒有從冰箱拿出蛋糕；第二，在標籤被修改時我人在一樓；第三，我過去替宿舍代收過很多冷藏包裹，也常提保冷袋，從來沒有拿錯別人的食物。所以我這次提著保冷袋也和失竊完全沒有關係，不能只因為袋子後來出現在自習室就懷疑我。','flaw','用過往代收冷藏物品未出錯概括本次保冷袋行為完全無關；歷史經驗與這次失物、時間點、共同聚餐情境並不具充分代表性。','過去代收經驗與本次保冷袋情境是否可比？哪些差異會改變結論？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (6,'1','真正該負責的是留下共用登入與標籤維護功能的許五澄。雖然是我輸入確認碼略過「私人物品」警示，但真正讓蛋糕容易被誤認的是前面沒有清除的標籤設定；就算我沒有按下確認，也可能由別人處理，而且盒子仍可能因為被移到公共料理桌而遭竊。我的操作不是唯一必要條件，所以不能因此說我對失竊或後續分食負有責任。','flaw','把「不是唯一必要條件」當成免除責任的充分理由；實際略過私人物品警示仍可能是重要促成行為，別人也可能做，不能抹去已發生的選擇。','一個行為不是唯一必要條件，是否仍可能是重要促成因素並產生責任？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (6,'2','蔡六禾應該負最大的責任。雖然是我把蛋糕從 B-9 移到公共料理桌，也沒有立刻把新增的公共貼紙撕掉，但如果蔡六禾沒有用保冷袋把蛋糕帶離廚房，大家就不可能在自習室看到那盒蛋糕並吃掉它。我當時只是整理冰箱，在時間壓力下迅速收拾桌面上的東西；真正造成失竊結果的是把東西帶走的人，所以主要責任應由蔡六禾承擔。','flaw','承認自己移動私人物品並未處理公共貼紙，卻把最後搬袋者當成最大責任；「若蔡六禾不搬就不會發生」不足以證明她的前置行為沒有獨立責任。','二寧與六禾的行為各自形成哪些獨立責任？哪些理由必須聯合使用？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (6,'3','現在證據顯示：有人改了蛋糕上的標示、有人移動盒子、有人略過警示、有人催促收拾、有人剪掉關鍵片段，也有人把保冷袋帶到自習室。要判斷這件事情該由誰負責，應分開比較各自偷吃蛋糕的意圖、在促成失竊的事件中的角色，以及事後誤導調查所造成的傷害，不能只歸咎於最後拿袋子的人。','reasonable','整合六人的不同行為與還原後的共同知情，並把共同偷吃意圖、各自促成作用與事後資訊傷害分開評估；沒有把單一角色當成全部原因。','如何分開評估共同意圖、實際取物、系統操作與事後掩護的責任？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (6,'4','陳一承應該負最大的責任。雖然我剪掉了三十一秒，讓畫面看起來像蔡六禾直接從冰箱拿走蛋糕，害她在宿舍群組被指責，但剪輯是在大家吃完之後才做的，和蛋糕被拿走沒有關係。如果陳一承沒有略過私人物品的警示，後面根本不會發生蛋糕失竊的事件；因此我剪輯的影片不應列入這起事件的主要責任。','flaw','剪輯發生在食物被吃之後，只能排除它造成最初失竊，不能排除它造成誤指、調查延誤與資訊傷害；也不能因此把全部責任推給陳一承。','應如何分開評估原始失竊與後續誤導？剪輯造成了哪些獨立後果？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (6,'5','不能把主要責任算在我身上，宿舍管理制度才是最大的問題。雖然我沒有登出共用平板，也留下測試用的標籤模板，但如果不是高三川催大家快點收桌面，陳一承也不會選擇直接略過警示。系統本來就允許用管理員帳號維護，代表這是制度設計，不是我個人的錯；智慧冰箱會因此被放在校務會議討論，之後還更容易爭取經費改善，搞不好是因禍得福。','flaw','先承認未登出共用平板與留下測試模板，接著把問題推給制度與時間壓力，最後以「有助改善」作為好處；這些理由不能抵銷已增加的風險。','制度缺陷能否免除個人維護義務？事後改善利益能否抵銷先前風險？');
INSERT INTO `ck_testimonies` (`level_no`, `char_key`, `text`, `correct`, `criterion`, `followup`) VALUES (6,'6','葉二寧應該負最大的責任。雖然我確實和大家一起吃了那盒蛋糕，但盒子是葉二寧先移到公共料理桌，還把「公共聚餐」的貼紙留在蛋糕盒旁邊；如果不是這樣，我就不會以為那是大家可以共享的食物。至於我把袋子帶到自習室，只是照大家當時的說法搬東西，所以主要責任應由葉二寧承擔。','flaw','葉二寧的移動與公共貼紙可能是重要條件，但蔡六禾承認搬袋並共同分食後，仍以「我以為可以吃」把責任主要外推；沒有處理群組訊息所顯示的共同知情。','如果她已知物品屬於予安，「以為可以吃」還能支持到什麼程度？');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (37,1,'1',1,'你有看清楚那個警示上寫了什麼嗎？','否','沒有。走廊那時候有人在聊天，我只確定紅燈亮過。要看門口監視器和系統紀錄，才知道警示內容和後來誰處理的。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (38,1,'2',1,'你有看到中間有人動過那一格嗎？','否','沒有。我只看到予安九點多放進去，還有後來那一格空了。中間發生什麼，我完全沒看到。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (39,1,'3',1,'你有確認過保冷袋裡裝的是什麼嗎？','否','沒有。我只看到她提著袋子從冰箱旁走開。她後來低頭不說話，我就自己接下去想了。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (40,1,'4',1,'你的影片有拍到她把蛋糕拿出來嗎？','否','沒有。我拍到她開冰箱、手伸進下層，鏡頭轉開，再切回來就空了。中間那段沒有畫面。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (41,1,'5',1,'其他層架正常，能證明 B-9 的標籤也正常嗎？','否','不能，這句我說得太滿。其他層架正常只代表其他層架。B-9 那一格要單獨查，共用登入和先前的設定也要一起查。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (42,1,'6',1,'除了「予安記錯」和「她自己移走」，還有別的可能嗎？','是','有。那段時間廚房不只我一個人，我也不是全程盯著冰箱。我只是覺得不會有人拿別人的東西。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (43,2,'1',1,'昨晚的巡查，你有逐項對過流程嗎？','不知道','我不確定。流程我很熟，但那時候走廊很吵，我沒有一項一項核。熟悉流程和那一次做對，本來就是兩件事。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (44,2,'2',1,'如果她的緊張是因為被整個宿舍指著，你的判斷會改變嗎？','是','會。畫面被停在她伸手那一格，全宿舍都在傳。這樣講起來，緊張也可能是被懷疑造成的，不一定是心虛。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (45,2,'3',1,'「有能力改系統」和「實際改了」之間，你手上有東西連得起來嗎？','否','沒有。我只知道她最懂後台。用哪台裝置、人在哪裡、改了什麼內容，我一項都說不出來。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (46,2,'4',1,'你的影片能證明她沒碰過 B-9 嗎？','不知道','我只有一個拍攝角度，冰箱門還擋住一部分下層。我能說的是我拍到的動作，拍不到的部分要別的紀錄補。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (47,2,'5',1,'有沒有資料可以單獨檢查 B-9 那一格的異常？','是','有。標籤模板的更新紀錄、那一格的感應紀錄，還有維護平板的登入紀錄。這些應該分開查，不能用整體故障率蓋過去。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (48,2,'6',1,'職務讓你常出現在廚房，這能證明你拿過蛋糕嗎？','否','不能。整層的人都能用那台冰箱。職務只說明我有機會，要判斷行為得看實際紀錄。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (49,3,'1',1,'共用平板的紀錄能指出是誰在操作嗎？','否','不能。維護模式只寫「管理模式登入」，不寫人。要有個人驗證——刷卡、指紋或個別帳號——才連得到某一個人。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (50,3,'2',1,'影片缺口除了有人故意剪掉，還可能有別的原因嗎？','是','……可能。存檔中斷、轉檔出錯都會少幾秒。而且就算真的是有人剪的，也還沒證明缺的就是拿蛋糕那一段。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (51,3,'3',1,'「系統誤標」和「蔡六禾直接拿走」涵蓋所有可能嗎？','否','不涵蓋。還有別人操作平板、標示貼錯位置，或事後有人把盒子搬走。我當時只想得到那兩種。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (52,3,'4',1,'你知道那通電話講了什麼嗎？','否','不知道。我只看到她臉色變僵。訊息寫什麼、電話講什麼，我都沒聽到——我是從順序自己接上去的。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (53,3,'5',1,'現在的紀錄能看出蛋糕最後去了哪裡嗎？','否','看不出來。紀錄只到「設定被改」。設定內容、盒子實體在哪、後面誰拿走，這是三件不同的事。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (54,3,'6',1,'不在修改現場，就代表整件事和你無關嗎？','不知道','……我原本是這樣講的。但我後來確實提過保冷袋，這一點我沒辦法說完全沒關係。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (55,4,'1',1,'如果沒有人催你，你還會輸入確認碼嗎？','不知道','我說不準。下午誤報兩次，我本來就傾向直接略過。催促讓我更快，但按下去的是我。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (56,4,'2',1,'除了時間接近，你能說出標籤怎麼讓蛋糕被帶走的嗎？','否','說不出來。我只看到這些事接連發生。中間是誰把它當成公共食物拿走的，我沒有那一段紀錄。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (57,4,'3',1,'如果二寧沒有移動盒子，就一定不會失竊嗎？','否','不一定。放在 B-9 也可能有人直接開冰箱拿。我只是抓了最顯眼的那一步。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (58,4,'4',1,'如果貼錯標籤但警示沒有被略過，結果會一樣嗎？','否','大概不會。警示還在的話，總得有人先確認歸屬。把整件事壓在她一個人身上，我承認是快了一點。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (59,4,'5',1,'人工確認能證明是誰拿走蛋糕嗎？','否','不能。人工確認只證明有人接受了那個狀態，連名字都不會留。誰拿走是另一回事。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (60,4,'6',1,'這幾個因素裡，哪些是可以避免的決策？','是','移動盒子、留著那張公共貼紙、按下確認碼，都是有人做的選擇。趕著夜間點名只是當時的情境背景。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (61,5,'1',1,'下午那兩次誤報和這一次，情境一樣嗎？','否','不一樣。下午那兩次是空層架測試，這次 B-9 裡真的放著有名字的盒子。這一點我剛剛講得太順了。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (62,5,'2',1,'要判斷是不是有人先起意，還缺什麼？','是','缺失竊前的群組對話，還有自習室那個外盒到底是不是予安那一盒。我這條推論只到「被當成公共食物帶走」。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (63,5,'3',1,'你能分開驗證「誰操作」和「誰預先知道結果」嗎？','否','分不開。我是從她最懂後台，一路猜到她預知結果、再猜到她是主謀的。中間每一步我都沒有紀錄。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (64,5,'4',1,'以前沒失竊過，能預測這一次嗎？','否','不能。以前也沒有人在公共冰箱裡放兩千多塊的東西。這次的條件跟平常不一樣。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (65,5,'5',1,'你那則要求登出、清除模板的訊息，有人回報完成嗎？','否','沒有。訊息顯示已讀，但沒有人回。模板留著、平板沒登出，這一段我自己也有責任。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (66,5,'6',1,'過去代收沒出錯，和這次的保冷袋可以比嗎？','否','……不太能比。以前是代收有單號的包裹，這次是自習室裡大家一起吃的東西。我知道差在哪裡。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (67,6,'1',1,'「不是唯一必要條件」等於「沒有責任」嗎？','否','不等於。就算別人也可能按下去，那一下是我按的。而且我按的時候，盒子上還貼著名字。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (68,6,'2',1,'把盒子移出去、留著那張公共貼紙，這兩件事有自己的責任嗎？','是','有。我不能只說「搬走的人才有責任」。移動和貼紙是我留下來的條件，這一項單獨就站得住。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (69,6,'3',1,'共同意圖、實際取物和事後誤導，需要分開評估嗎？','是','要。群組裡的約定是一件事，誰動手是另一件，失竊之後我把話題引向別人又是第三件。混在一起講就會有人被多算、有人被少算。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (70,6,'4',1,'剪輯發生在吃完之後，就和責任無關嗎？','否','不是。它沒有造成失竊，但害六禾被整個宿舍指著，也讓調查慢了好幾天。那是另外一筆。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (71,6,'5',1,'制度有缺陷，就能免除你自己的維護義務嗎？','否','不能。我自己發訊息要大家登出，卻沒有清掉模板。之後就算爭取到經費改善，也補不回這一次。');
INSERT INTO `ck_questions` (`id`, `level_no`, `char_key`, `seq`, `q`, `a`, `detail`) VALUES (72,6,'6',1,'你當時知道那盒是予安的嗎？','是','知道。群組裡寫得很清楚。我說「以為可以吃」，其實是大家都同意了，我才這樣講。');
INSERT INTO `ck_config` (`ck_key`, `ck_value`, `is_public`) VALUES ('brief','{\"body\": \"霧城大學七舍用 COLD-6 智慧冰箱管理公共廚房的冷藏物品。週五晚上，住戶蘇予安把一盒價值新臺幣 2,680 元的月蝕巧克力莓果千層蛋糕放進 B-9 層，盒上貼著姓名與「私人物品」標籤。十一點左右她回來取，櫃位已經空了，只剩一小段被撕下的透明膠帶。走廊監視器沒有正對冰箱內部；一段十二秒的影片在宿舍群組被大量轉傳，畫面停在樓層總務蔡六禾伸手進冰箱的瞬間。六名學生那晚都在交誼廳與公共廚房附近，每個人都只說自己看到的那一段。\", \"lead\": \"晚上十點四十七分零九秒，COLD-6 智慧冰箱跳出一行紀錄：「B-9 標籤狀態異常。」\", \"question\": \"蛋糕到底去了哪裡？如果沒有人單獨偷走，就沒有人該負責嗎？\"}',1);
INSERT INTO `ck_config` (`ck_key`, `ck_value`, `is_public`) VALUES ('debrief','{\"items\": [\"找證據：區分可驗證事實、意見、推論與傳聞，並標明每項證據能證明與不能證明的範圍。\", \"辨認假設：找出支撐結論卻沒說出口的前提——職務、專業、緊張反應、系統可靠度——並檢查它能不能驗證。\", \"演繹推論：把說法拆成前提與結論，檢查推論形式是否有效，不把帳號、裝置與實際操作者混為一談。\", \"解釋因果關係：區分直接原因、促成條件、必要條件與充分條件，不把時間先後或同時出現當成因果。\", \"歸納推論：用機率語言比較競爭解釋，注意樣本是否獨立、情境是否可比、是否以偏概全。\", \"論證：組織可獨立成立與需要聯合的理由，並分開評估共同意圖、個別行為與事後誤導的責任。\"], \"title\": \"Debriefing｜你剛剛用到的批判思考技巧\", \"closing\": \"最後一件事：這個案子裡，六個人在不同關卡都說過合理的話——但合理不等於行為正當。判斷「推論品質」、「證據強度」、「共同意圖」與「行為責任」是四件要分開做的事。批判思考不是用來證明某個人清白，而是讓你知道手上的證據能支持到哪裡、不能支持到哪裡。\"}',0);
