INSERT INTO `ck_config` (`ck_key`, `ck_value`, `is_public`) VALUES ('truth','{\"body\": \"六名學生私下組成名為「夜食會」的群組，長期把宿舍裡價格較高的私人物品說成「沒人會追究的小物共享」，並約定被詢問時只描述自己看到的片段。這一次，六人都知道蛋糕屬於蘇予安，仍在群組中同意晚上一起分食。許五澄未登出共用平板並留下測試用的標籤模板；葉二寧把蛋糕從 B-9 移到公共料理桌，公共聚餐貼紙留在盒邊；陳一承看見私人物品警示後仍輸入值勤碼人工略過；高三川催促收桌，失竊後又用二選一說法把注意力引向別人；蔡六禾把裝著蛋糕的保冷袋帶到自習室；羅四影事後剪掉關鍵三十一秒，使最初流傳的影片看起來像蔡六禾單獨從冰箱拿走蛋糕。自習室影像與回收包裝證實六人共同分食。\", \"points\": [{\"a\": \"從 B-9 被移到公共料理桌（料理桌感測在相近時間增加約 1.7 公斤），私人物品警示被人工略過後，裝進保冷袋帶到自習室，由六人共同分食。\", \"q\": \"蛋糕到底去了哪裡？\"}, {\"a\": \"不是。被剪掉的三十一秒還原後，她從冰箱拿出的只有兩瓶貼著「公共飲料」標籤的氣泡水。但她後來確實提著裝有蛋糕的保冷袋離開廚房，也參與分食。\", \"q\": \"蔡六禾就是影片裡拿走蛋糕的人嗎？\"}, {\"a\": \"不是。下午兩次誤報都發生在空層架測試，與這次放有實體私人物品的情境不同。系統確實跳出了「私人物品標籤不一致」，是人按下值勤碼略過的。\", \"q\": \"是系統出錯嗎？\"}, {\"a\": \"共用平板的維護模式不記錄個人姓名，沒有任何紀錄能指認操作者本人。可以確定的是：她沒有登出共用平板，也沒有清除「公共聚餐」測試模板，讓混淆的條件留在系統裡。\", \"q\": \"許五澄有改標籤嗎？\"}, {\"a\": \"沒有單一原因。移動、標示混淆、警示被略過、收拾壓力共同促成，而背後還有群組裡先形成的共同意圖。每一個單一行為都有正常的替代解釋——這正是它難以判斷的原因。\", \"q\": \"誰造成失竊？\"}, {\"a\": \"要分開算三件事：群組裡的共同分食意圖、各自的促成行為（登入未登出、移動、略過警示、催促、搬運），以及事後誤導所造成的傷害（剪掉三十一秒、把話題引向他人）。責任不是只有一份，也不能全推給最後提袋的人。\", \"q\": \"那到底誰該負責？\"}], \"headline\": \"沒有人單獨偷走。六個人都在。\"}',0);
INSERT INTO `ck_config` (`ck_key`, `ck_value`, `is_public`) VALUES ('ZONES','{\"flaw\": {\"key\": \"flaw\", \"hint\": \"技巧使用有瑕疵；上牆保留其中值得追查的破綻\", \"label\": \"破綻證據牆\"}, \"reasonable\": {\"key\": \"reasonable\", \"hint\": \"來源、範圍與限制清楚，可納入證據整理\", \"label\": \"合理說法\"}}',1);
